(function() {
    const styles = `
        #custom-network-bar {
            width: 100%;
            display: block;
            z-index: 99999;
            position: relative;
            background: linear-gradient(90deg, #000 0%, #1a1a1a 50%, #000 100%);
            border-bottom: 1px solid rgba(255, 255, 255, 0.15);
            box-shadow: 0 4px 10px rgba(0,0,0,0.5);
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            height: 50px;
            transition: all 0.4s ease-in-out;
            transform-origin: top;
        }

        #custom-network-bar.hide-animated {
            transform: translateY(-100%);
            opacity: 0;
            margin-top: -50px; 
        }

        #custom-network-bar .network-inner {
            display: flex;
            align-items: center;
            height: 100%;
            padding: 0 15px;
            max-width: 100%;
            overflow: hidden;
        }

        #custom-network-bar .brand-logo {
            font-size: 16px;
            font-weight: 900;
            text-transform: uppercase;
            font-style: italic;
            letter-spacing: 0.5px;
            margin-right: 15px;
            background: linear-gradient(to right, #ff0000, #ffff00, #00ff00, #00ffff, #0000ff, #ff00ff, #ff0000);
            background-size: 400% auto;
            -webkit-background-clip: text;
            text-fill-color: transparent;
            -webkit-text-fill-color: transparent;
            white-space: nowrap;
            cursor: pointer;
            animation: rainbowMove 3s linear infinite;
        }

        @keyframes rainbowMove {
            0% { background-position: 0% center; }
            100% { background-position: 400% center; }
        }

        #custom-network-bar .divider {
            width: 1px;
            height: 24px;
            background: rgba(255,255,255,0.2);
            margin-right: 15px;
            flex-shrink: 0;
        }

        #custom-network-bar .network-links {
            display: flex;
            align-items: center;
            gap: 10px;
            overflow-x: auto;
            height: 100%;
            flex: 1;
            scrollbar-width: none;  
            -ms-overflow-style: none;
        }

        #custom-network-bar .network-links::-webkit-scrollbar {
            display: none;  
        }

        #custom-network-bar .net-btn {
            text-decoration: none;
            color: #fff;
            font-weight: 700;
            font-size: 13px;
            padding: 6px 16px;
            border-radius: 50px;
            background: rgba(255, 255, 255, 0.1);
            border: 1px solid rgba(255, 255, 255, 0.15);
            transition: all 0.2s ease;
            white-space: nowrap;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        #custom-network-bar .net-btn:hover {
            transform: scale(1.05);
            background: #fff;
            color: #000;
            box-shadow: 0 0 15px rgba(255,255,255,0.5);
        }

        #custom-network-bar .net-btn.blue { background: rgba(0, 210, 255, 0.15); border-color: rgba(0, 210, 255, 0.3); }
        #custom-network-bar .net-btn.orange { background: rgba(255, 80, 0, 0.15); border-color: rgba(255, 80, 0, 0.3); }
        #custom-network-bar .net-btn.green { background: rgba(0, 255, 100, 0.15); border-color: rgba(0, 255, 100, 0.3); }
        #custom-network-bar .net-btn.purple { background: rgba(180, 0, 255, 0.15); border-color: rgba(180, 0, 255, 0.3); }

        #custom-network-bar .net-btn.blue:hover { background: #00d2ff; color: #fff; box-shadow: 0 0 15px #00d2ff; }
        #custom-network-bar .net-btn.orange:hover { background: #ff5e00; color: #fff; box-shadow: 0 0 15px #ff5e00; }
        #custom-network-bar .net-btn.green:hover { background: #00ff6a; color: #000; box-shadow: 0 0 15px #00ff6a; }
        #custom-network-bar .net-btn.purple:hover { background: #aa00ff; color: #fff; box-shadow: 0 0 15px #aa00ff; }

        .net-close-btn {
            background: rgba(255, 255, 255, 0.1);
            color: #fff;
            border: 1px solid rgba(255, 255, 255, 0.2);
            border-radius: 50%;
            width: 28px;
            height: 28px;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            margin-left: 15px;
            font-weight: bold;
            font-size: 12px;
            transition: all 0.2s ease;
            flex-shrink: 0;
        }
        .net-close-btn:hover {
            background: #ff0055;
            border-color: #ff0055;
            transform: scale(1.1);
        }
    `;

    const topBarHtml = `
        <div class="network-inner">
            <div class="brand-logo" onclick="window.scrollTo(0,0)">
                NEW WEB SITES >>
            </div>
            
            <div class="divider"></div>

            <div class="network-links">
                <a href="https://www.symbaloo.com/mix/newunblockedgames?lang=EN" target="_blank" title="symbaloo" class="net-btn purple">
                    <span>🔥</span> New Symbaloo <span>🔥</span>
                </a>

                <a href="https://agarlive.site" target="_blank" title="station" class="net-btn">
                    <span>⚽</span> AGARIO<span>⚽</span>
                </a>
                <a href="https://edujojo.live/" target="_blank" title="gitlab" class="net-btn green">
                    <span>🚀</span> Edujojo Live
                </a>
                <a href="https://edujojo.website/" target="_blank" title="study40" class="net-btn orange">
                    <span>🔥</span> Edujojo Website
                </a>
                
                <a href="https://edujojo.site" target="_blank" title="edujojo" class="net-btn blue">
                    <span>🎮</span> Edujojo Site
                </a> 
                <a href="https://edujojo.online/" target="_blank" title="fast study" class="net-btn blue">
                    <span>📚</span> Edujojo Online
                </a>

                <a href="https://edujojo.space/" target="_blank" title="taktak" class="net-btn green">
                    <span>🧩</span> Edujojo Space
                </a>
                      
                <a href="https://edujojo.top/" target="_blank" title="patpat" class="net-btn purple">
                    <span>💎</span> Edujojo Top
                </a>
                
                <a href="https://classnotes30.online/" target="_blank" title="ahoy" class="net-btn">
                    <span>⚽</span> Classnotes 30
                </a>

                <a href="https://classnotes50.online/" target="_blank" title="ahoy" class="net-btn orange">
                    <span>🎬</span> Classnotes 50
                </a>
                      
            </div>
            
            <div class="divider"></div>
            <div class="net-close-btn" id="close-topbar" title="Kapat">✖</div>
        </div>
    `;

    function injectNetworkBar() {
       
        const styleSheet = document.createElement("style");
        styleSheet.innerText = styles;
        document.head.appendChild(styleSheet);

        const barContainer = document.createElement("div");
        barContainer.id = "custom-network-bar";
        barContainer.innerHTML = topBarHtml;
        document.body.prepend(barContainer);

        document.getElementById('close-topbar').addEventListener('click', function(e) {
            e.preventDefault();
            const topBar = document.getElementById('custom-network-bar');
            topBar.classList.add('hide-animated');
            // Animasyon süresi (400ms) bittikten sonra DOM'dan tamamen sil
            setTimeout(() => {
                if(topBar) topBar.remove();
            }, 400);
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', injectNetworkBar);
    } else {
        injectNetworkBar();
    }

})();
